322			assertHeaderConflict(t, storeHeader(t, state, "chain-a", 100, root, true),
323				"chain-a", 100, root, "0xaaa")
324		}
325		// The original raw string is still accepted byte-for-byte.
326		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
327			t.Fatalf("byte-identical root must stay idempotent: code=%d stderr=%q", r.code, r.stderr)
328		}
329	}
