11	// runVerify drives a deterministic scenario in a temporary (or --state given)
12	// directory so every terminal state, waiting, expiry, replay, restart and
13	// locking behaviour can be observed offline.
14	func runVerify(args []string) error {
15		stateDir := ""
16		for i := 0; i < len(args); i++ {
17			switch args[i] {
18			case "--state":
19				if i+1 >= len(args) {
20					return fmt.Errorf("--state requires a directory")
21				}
22				stateDir = args[i+1]
23				i++
24			default:
25				return fmt.Errorf("unknown verify flag %q", args[i])
26			}
27		}
28		if stateDir == "" {
29			var err error
30			stateDir, err = os.MkdirTemp("", "relayproof-verify-")
31			if err != nil {
32				return err
33			}
34			defer os.RemoveAll(stateDir)
35		}
36		fmt.Println("verify state dir:", stateDir)
37	
38		verifyAmbiguousPaths()
39	
40		must := func(step string, err error) {
41			if err != nil {
42				panic(step + ": " + err.Error())
43			}
44		}
45	
46		q, err := relayproof.Open(stateDir)
47		must("open", err)
48	
49		must("register a", q.RegisterSource("chain-a"))
50		must("header a@80 untrusted", q.UpsertHeader(relayproof.Header{Chain: "chain-a", Height: 80, Root: "0x80"}))
51	
52		// Two messages share one nonce combination; one will win, one replay.
53		_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "m-win", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 100}})
54		must("submit m-win", err)
55		_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "m-lose", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 100}})
56		must("submit m-lose", err)
57		// Expiring message (proof height beyond the 100 header, so it waits until
58		// its 5000 expiry) and an unknown-source message.
59		_, err = q.Submit(relayproof.Envelope{
60			Message:   relayproof.Message{ID: "m-exp", From: "chain-a", To: "chain-b", Nonce: 8, ProofAt: 1000},
61			ExpiresAt: 5000,
62		})
63		must("submit m-exp", err)
64		_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "m-alien", From: "chain-x", To: "chain-b", Nonce: 1, ProofAt: 1}})
65		must("submit m-alien", err)
66	
67		step := func(label string, now int64) {
68			rep, err := q.Advance(now)
69			must(label, err)
70			fmt.Printf("advance %d -> %d result(s)\n", rep.Now, len(rep.Results))
71			for _, r := range rep.Results {
72				fmt.Printf("    %-8s %-14s %s\n", r.ID, r.Status, r.Reason)
73			}
74		}
75	
76		step("t=1000 header short", 1000) // win/lose/exp waiting; alien unknown-source
77		must("header a@100 trusted", q.UpsertHeader(relayproof.Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}))
78		// Header does not bypass the 1s retry: win/lose stay waiting until 2000.
79		step("t=1500 retry not due", 1500)
80		step("t=2000 retry due, win delivers", 2000) // win success, lose replay
81		step("t=5000 expiry instant", 5000)          // m-exp expired exactly at boundary
82	
83		printRecords(q)
84		must("close before reopen", q.Close())
85	
86		// Restart: delivered message must not deliver again, state fully restored.
87		q2, err := relayproof.Open(stateDir)
88		must("reopen", err)
89		rep, err := q2.Advance(9000)
90		must("advance after reopen", err)
91		if len(rep.Results) != 0 {
92			return fmt.Errorf("terminal messages processed again after restart: %+v", rep.Results)
93		}
94		fmt.Println("restart at 9000: 0 results, last advanced time =", q2.Now())
95	
96		// Second concurrent opener must be refused; directory reusable after close.
97		if _, err := relayproof.Open(stateDir); err == nil {
98			return fmt.Errorf("concurrent open unexpectedly succeeded")
99		} else {
100			fmt.Println("concurrent open refused:", err)
101		}
102		must("final close", q2.Close())
103		q3, err := relayproof.Open(stateDir)
104		if err != nil {
105			return fmt.Errorf("directory not reusable after holder exit: %w", err)
106		}
107		fmt.Println("directory reusable after holder closed")
108		if err := q3.Close(); err != nil {
109			return err
110		}
111		fmt.Println("verify: OK")
112		return nil
113	}
114	
115	func printRecords(q *relayproof.Queue) {
116		fmt.Println("records (submission order):")
117		for _, r := range q.Queries() {
118			retry := "-"
119			if r.NextRetry != 0 {
120				retry = fmt.Sprintf("%d", r.NextRetry)
121			}
122			fmt.Printf("    %-8s %-14s retry=%-6s %s\n", r.ID, r.Status, retry, r.Reason)
123		}
124	}
125	
126	// verifyAmbiguousPaths drives the replay-protection fix: two distinct routing
127	// paths that flatten to the same string under any delimiter-joined key must
128	// both deliver. The colon pair is expressible on the command line as well;
129	// the U+0000 pair can only be submitted through the Go API because argv
130	// strings cannot contain a NUL byte. A genuine same-path repeat must still
131	// be a replay whose reason names the real winner, and the consumption
132	// relationships must survive a close/reopen cycle.
133	func verifyAmbiguousPaths() {
134		// --- In-memory Verify entry point. ---
135		headers := map[string]relayproof.Header{
136			"a:b": {Chain: "a:b", Height: 100, Trusted: true},
137			"a":   {Chain: "a", Height: 100, Trusted: true},
138		}
139		consumed := map[string]bool{}
140		msgs := []relayproof.Message{
141			{ID: "mem-col-1", From: "a:b", To: "c", Nonce: 7, ProofAt: 10},
142			{ID: "mem-col-2", From: "a", To: "b:c", Nonce: 7, ProofAt: 10},
143			{ID: "mem-nul-1", From: "a\x00b", To: "c", Nonce: 7, ProofAt: 10},
144			{ID: "mem-nul-2", From: "a", To: "b\x00c", Nonce: 7, ProofAt: 10},
145		}
146		fmt.Println("ambiguous-path check (in-memory Verify):")
147		for _, m := range msgs {
148			// The two NUL-bearing messages also need their own source header.
149			headers[m.From] = relayproof.Header{Chain: m.From, Height: 100, Trusted: true}
150			d := relayproof.Verify(headers, m, consumed)
151			fmt.Printf("    %-10s %-10s %s\n", d.Message, d.Status, d.Reason)
152			if d.Status != "delivered" {
153				panic("distinct path " + m.ID + " was mistaken for a replay")
154			}
155		}
156		d := relayproof.Verify(headers, msgs[0], consumed)
157		if d.Status != "rejected" || !strings.Contains(d.Reason, "replay") {
158			panic("genuine repeat of mem-col-1 was not a replay: " + d.Reason)
159		}
160		fmt.Printf("    %-10s %-10s %s\n", d.Message, d.Status, d.Reason)
161	
162		// --- Durable queue, including persistence across reopen. ---
163		dir, err := os.MkdirTemp("", "relayproof-verify-paths-")
164		if err != nil {
165			panic(err)
166		}
167		defer os.RemoveAll(dir)
168	
169		q, err := relayproof.Open(dir)
170		if err != nil {
171			panic(err)
172		}
173		for _, chain := range []string{"a:b", "a", "a\x00b"} {
174			if err := q.RegisterSource(chain); err != nil {
175				panic(err)
176			}
177			if err := q.UpsertHeader(relayproof.Header{Chain: chain, Height: 100, Trusted: true}); err != nil {
178				panic(err)
179			}
180		}
181		submit := func(id, from, to string) {
182			_, err := q.Submit(relayproof.Envelope{
183				Message: relayproof.Message{ID: id, From: from, To: to, Nonce: 7, ProofAt: 10},
184			})
185			if err != nil {
186				panic(err)
187			}
188		}
189		submit("q-col-1", "a:b", "c")
190		submit("q-col-2", "a", "b:c")
191		submit("q-nul-1", "a\x00b", "c")
192		submit("q-dup", "a:b", "c") // genuinely the same triple as q-col-1
193	
194		rep, err := q.Advance(1000)
195		if err != nil {
196			panic(err)
197		}
198		fmt.Println("ambiguous-path check (durable queue):")
199		want := map[string]string{
200			"q-col-1": relayproof.StatusSuccess,
201			"q-col-2": relayproof.StatusSuccess,
202			"q-nul-1": relayproof.StatusSuccess,
203			"q-dup":   relayproof.StatusReplay,
204		}
205		got := map[string]relayproof.Result{}
206		for _, r := range rep.Results {
207			got[r.ID] = r
208			fmt.Printf("    %-10s %-14s %s\n", r.ID, r.Status, r.Reason)
209		}
210		for id, st := range want {
211			r, ok := got[id]
212			if !ok || r.Status != st {
213				panic(fmt.Sprintf("%s: want %s got %+v", id, st, r))
214			}
215		}
216		if !strings.Contains(got["q-dup"].Reason, "q-col-1") {
217			panic("replay reason must name the real winner q-col-1: " + got["q-dup"].Reason)
218		}
219		if err := q.Close(); err != nil {
220			panic(err)
221		}
222	
223		q2, err := relayproof.Open(dir)
224		if err != nil {
225			panic(err)
226		}
227		defer q2.Close()
228		rep, err = q2.Advance(2000)
229		if err != nil {
230			panic(err)
231		}
232		if len(rep.Results) != 0 {
233			panic(fmt.Sprintf("historical successes processed again after reopen: %+v", rep.Results))
234		}
235		for id, st := range want {
236			r, ok := q2.Query(id)
237			if !ok || r.Status != st {
238				panic(fmt.Sprintf("after reopen %s: want %s got %+v", id, st, r))
239			}
240			// Full chain names, including the NUL bytes, must survive intact.
241			if id == "q-col-1" && (r.From != "a:b" || r.To != "c") {
242				panic(fmt.Sprintf("%s names rewritten: %q -> %q", id, r.From, r.To))
243			}
244			if id == "q-nul-1" && (r.From != "a\x00b" || r.To != "c") {
245				panic(fmt.Sprintf("%s names rewritten: %q -> %q", id, r.From, r.To))
246			}
247		}
248		// New id on the path that shares the old NUL-flattened identifier with the
249		// historical q-nul-1 ("a\x00b"->"c" and "a"->"b\x00c" used to collide).
250		// It is a different triple, so it must deliver; reusing q-nul-1's exact
251		// triple under any new id must still be a replay.
252		if _, err := q2.Submit(relayproof.Envelope{
253			Message: relayproof.Message{ID: "q-nul-1-again", From: "a\x00b", To: "c", Nonce: 7, ProofAt: 10},
254		}); err != nil {
255			panic(err)
256		}
257		if _, err := q2.Submit(relayproof.Envelope{
258			Message: relayproof.Message{ID: "q-nul-2", From: "a", To: "b\x00c", Nonce: 7, ProofAt: 10},
259		}); err != nil {
260			panic(err)
