142	// assertSubmitMatchesQuery requires the submit echo and the single-record query
143	// to agree on every field both views expose.
144	func assertSubmitMatchesQuery(t *testing.T, sub cliSubmitRecord, q cliFullRecord) {
145		t.Helper()
146		if sub.ID != q.ID || sub.Status != q.Status || sub.Reason != q.Reason ||
147			sub.Attempts != q.Attempts || sub.NextRetry != q.NextRetry ||
148			sub.ExpiresAt != q.ExpiresAt {
149			t.Fatalf("submit output %+v disagrees with stored record %+v", sub, q)
150		}
151	}
