153	// assertContentConflict requires the exact CLI surface of a message-content
154	// conflict: exit 13, a stderr line naming both the id-conflict category and
155	// the differing content, the message id, and nothing on stdout.
156	func assertContentConflict(t *testing.T, r cliResult, id string) {
157		t.Helper()
158		if r.code != 13 {
159			t.Fatalf("want exit 13 for %s, got %d (stdout=%q stderr=%q)", id, r.code, r.stdout, r.stderr)
160		}
161		if r.stdout != "" {
162			t.Fatalf("a rejected submit must not print a success record: %q", r.stdout)
163		}
164		for _, want := range []string{"message id conflict", "different content", id} {
165			if !strings.Contains(r.stderr, want) {
166				t.Fatalf("stderr for %s missing %q:\n%s", id, want, r.stderr)
167			}
168		}
169	}
170	
171	// assertTerminalReject requires exit 14 naming the terminal category, the id
172	// and its current status; a terminal id must never be downgraded to a content
173	// conflict (13), even when the resubmitted content differs.
174	func assertTerminalReject(t *testing.T, r cliResult, id, status string) {
175		t.Helper()
176		if r.code != 14 {
177			t.Fatalf("want exit 14 for terminal %s, got %d (stdout=%q stderr=%q)", id, r.code, r.stdout, r.stderr)
178		}
179		if r.stdout != "" {
180			t.Fatalf("a rejected submit must not print a success record: %q", r.stdout)
181		}
182		for _, want := range []string{"terminal", id, status} {
183			if !strings.Contains(r.stderr, want) {
184				t.Fatalf("stderr for %s missing %q:\n%s", id, want, r.stderr)
185			}
186		}
187		if strings.Contains(r.stderr, "different content") {
188			t.Fatalf("terminal %s must be reported as terminal, not content conflict: %s", id, r.stderr)
189		}
190	}
