192	// First submission leaves the message pending; submitting byte-identical
193	// content again succeeds and echoes the same existing record, the listing still
194	// contains exactly one entry for that id, and the original submission position
195	// does not move relative to messages submitted around the duplicate.
196	func TestCLISubmitIdenticalPendingReturnsExistingRecord(t *testing.T) {
197		state := t.TempDir()
198		registerSource(t, state, "chain-a")
199		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
200			t.Fatalf("store header: %v", r)
201		}
202	
203		spec := cliSubmitSpec{
204			id: "m1", from: "chain-a", to: "chain-b", nonce: 7,
205			proofAt: 90, payload: "hello", expiresAt: 9_000_000_000_000,
206		}
207		first, rawFirst := mustSubmit(t, state, spec)
208		wantFirst := cliSubmitRecord{
209			ID: "m1", Status: "pending", Reason: "awaiting first processing",
210			Attempts: 0, ExpiresAt: 9_000_000_000_000,
211		}
212		if first != wantFirst {
213			t.Fatalf("first submit output wrong: %+v", first)
214		}
215	
216		// A sibling after m1 but before the duplicate pins m1's seq position.
217		mustSubmit(t, state, cliSubmitSpec{
218			id: "sib-before", from: "chain-a", to: "chain-b", nonce: 10,
219			proofAt: 10, payload: "s1", expiresAt: 9_000_000_000_000,
220		})
221	
222		second, rawSecond := mustSubmit(t, state, spec)
223		if rawSecond != rawFirst || second != first {
224			t.Fatalf("identical resubmit must echo the same record:\nfirst =%q\nsecond=%q", rawFirst, rawSecond)
225		}
226	
227		mustSubmit(t, state, cliSubmitSpec{
228			id: "sib-after", from: "chain-a", to: "chain-b", nonce: 11,
229			proofAt: 10, payload: "s2", expiresAt: 9_000_000_000_000,
230		})
231	
232		stored := queryFull(t, state, "m1")
233		assertSubmitMatchesQuery(t, second, stored)
234		if stored.From != spec.from || stored.To != spec.to || stored.Nonce != spec.nonce ||
235			stored.Payload != spec.payload || stored.ProofAt != spec.proofAt ||
236			stored.ExpiresAt != spec.expiresAt {
237			t.Fatalf("stored content changed on identical resubmit: %+v", stored)
238		}
239	
240		all := queryAll(t, state)
241		if got := recordIDs(all); len(got) != 3 || got[0] != "m1" || got[1] != "sib-before" || got[2] != "sib-after" {
242			t.Fatalf("duplicate submit must not add an entry or move the original seq: %v", got)
243		}
244	}
