246	// Omitting --payload and --expires-at is the same message as passing "" and 0
247	// explicitly; the duplicate returns the existing record, the listing has one
248	// entry, and expiry 0 still means never (the message delivers on advance).
249	func TestCLISubmitOmittedPayloadAndExpiryEqualExplicitZero(t *testing.T) {
250		state := t.TempDir()
251		registerSource(t, state, "chain-a")
252		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
253			t.Fatalf("store header: %v", r)
254		}
255	
256		omitted := cliSubmitSpec{
257			id: "d1", from: "chain-a", to: "chain-b", nonce: 1,
258			proofAt: 10, omitPayload: true, omitExpires: true,
259		}
260		first, rawFirst := mustSubmit(t, state, omitted)
261		if first.Status != "pending" || first.ExpiresAt != 0 || first.NextRetry != 0 || first.Attempts != 0 {
262			t.Fatalf("default submit output wrong: %+v", first)
263		}
264		if strings.Contains(rawFirst, "expiresAtMs") || strings.Contains(rawFirst, "nextRetryMs") {
265			t.Fatalf("zero expiry/no-retry fields must be omitted: %q", rawFirst)
266		}
267	
268		explicit := omitted
269		explicit.omitPayload, explicit.omitExpires = false, false
270		explicit.payload, explicit.expiresAt = "", 0
271		second, rawSecond := mustSubmit(t, state, explicit)
272		if rawSecond != rawFirst || second != first {
273			t.Fatalf("explicit empty payload/zero expiry must equal the defaults:\n%q\n%q", rawFirst, rawSecond)
274		}
275	
276		all := queryAll(t, state)
277		if len(all) != 1 || all[0].ID != "d1" || all[0].Payload != "" || all[0].ExpiresAt != 0 {
278			t.Fatalf("duplicate default submit must not add an entry: %+v", all)
279		}
280	
281		rep := advanceCLI(t, state, 1_700_000_000_000)
282		if got := resultFor(t, rep, "d1"); got.Status != "success" {
283			t.Fatalf("expiry 0 must mean never expire; message should deliver: %+v", got)
284		}
285	}
