287	// Once the first processing has parked a message in waiting (no trusted header
288	// at the proof height yet), an identical resubmit returns the CURRENT waiting
289	// record — status, reason, attempt count and next retry time — not a fresh
290	// pending echo. It must not process early, add an attempt or reschedule the
291	// retry, and the submit echo must match a single-id query exactly.
292	func TestCLISubmitIdenticalWaitingReturnsCurrentWaitingRecord(t *testing.T) {
293		state := t.TempDir()
294		registerSource(t, state, "chain-a")
295		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
296			t.Fatalf("store header: %v", r)
297		}
298	
299		spec := cliSubmitSpec{
300			id: "w1", from: "chain-a", to: "chain-b", nonce: 8,
301			proofAt: 110, payload: "world", expiresAt: 9_000_000_000_000,
302		}
303		mustSubmit(t, state, spec)
304		rep := advanceCLI(t, state, 1_700_000_000_000)
305		if got := resultFor(t, rep, "w1"); got.Status != "waiting" {
306			t.Fatalf("setup: want waiting, got %+v", got)
307		}
308	
309		wantWaiting := cliSubmitRecord{
310			ID: "w1", Status: "waiting",
311			Reason:    "waiting for trusted header covering height 110 (current 100)",
312			Attempts:  1,
313			NextRetry: 1_700_000_001_000,
314			ExpiresAt: 9_000_000_000_000,
315		}
316		echo, rawEcho := mustSubmit(t, state, spec)
317		if echo != wantWaiting {
318			t.Fatalf("identical resubmit must return the current waiting record: %+v\n%s", echo, rawEcho)
319		}
320		assertSubmitMatchesQuery(t, echo, queryFull(t, state, "w1"))
321		if all := queryAll(t, state); len(all) != 1 || all[0].ID != "w1" {
322			t.Fatalf("waiting duplicate must not add a queue entry: %+v", all)
323		}
324	
325		// Advancing half a second early processes nothing; the duplicate submit
326		// must neither have advanced the clock nor rescheduled the retry.
327		early := advanceCLI(t, state, 1_700_000_000_500)
328		if len(early.Results) != 0 {
329			t.Fatalf("nothing is due before the retry instant: %+v", early.Results)
330		}
331		echo2, _ := mustSubmit(t, state, spec)
332		if echo2 != wantWaiting {
333			t.Fatalf("waiting record must keep status/reason/attempts/retry: %+v", echo2)
334		}
335		if got := queryFull(t, state, "w1"); got.Status != "waiting" ||
336			got.Reason != wantWaiting.Reason || got.Attempts != 1 ||
337			got.NextRetry != 1_700_000_001_000 {
338			t.Fatalf("stored waiting record changed: %+v", got)
339		}
340	}
