342	// Identity of content covers every field: source chain, destination chain,
343	// nonce, payload, proof height and absolute expiry. Changing any single one of
344	// them on a pending id must exit 13 as a content conflict and leave the
345	// original content and pending state stored, with no second entry.
346	func TestCLISubmitContentConflictExit13ForEveryField(t *testing.T) {
347		base := cliSubmitSpec{
348			id: "m", from: "chain-a", to: "chain-b", nonce: 7,
349			proofAt: 90, payload: "hello", expiresAt: 9_000_000_000_000,
350		}
351		cases := []struct {
352			name   string
353			mutate func(*cliSubmitSpec)
354		}{
355			{"source chain", func(s *cliSubmitSpec) { s.from = "chain-other" }},
356			{"destination chain", func(s *cliSubmitSpec) { s.to = "chain-c" }},
357			{"nonce", func(s *cliSubmitSpec) { s.nonce = 8 }},
358			{"payload", func(s *cliSubmitSpec) { s.payload = "HELLO" }},
359			{"proof height", func(s *cliSubmitSpec) { s.proofAt = 91 }},
360			{"absolute expiry", func(s *cliSubmitSpec) { s.expiresAt = 9_000_000_000_001 }},
361		}
362		for _, tc := range cases {
363			t.Run(tc.name, func(t *testing.T) {
364				state := t.TempDir()
365				mustSubmit(t, state, base)
366	
367				changed := base
368				tc.mutate(&changed)
369				assertContentConflict(t, submitRaw(t, state, changed), "m")
370	
371				got := queryFull(t, state, "m")
372				if got.From != base.from || got.To != base.to || got.Nonce != base.nonce ||
373					got.Payload != base.payload || got.ProofAt != base.proofAt ||
374					got.ExpiresAt != base.expiresAt {
375					t.Fatalf("conflicting submit overwrote original content: %+v", got)
376				}
377				if got.Status != "pending" || got.Reason != "awaiting first processing" ||
378					got.Attempts != 0 || got.NextRetry != 0 {
379					t.Fatalf("conflicting submit changed pending state: %+v", got)
380				}
381				if all := queryAll(t, state); len(all) != 1 || all[0].ID != "m" {
382					t.Fatalf("conflicting submit must not add an entry: %+v", all)
383				}
384			})
385		}
386	}
