388	// Changing just the proof height or just the expiry of a WAITING record is
389	// still a 13 conflict: the original content, status, reason, attempt count and
390	// scheduled retry all survive, an early advance still processes nothing, and
391	// the message later delivers against its ORIGINAL proof height (a trusted
392	// header at 110 covers the kept proof 110, not the rejected 111).
393	func TestCLISubmitWaitingConflictKeepsContentAndSchedule(t *testing.T) {
394		state := t.TempDir()
395		registerSource(t, state, "chain-a")
396		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
397			t.Fatalf("store header: %v", r)
398		}
399		spec := cliSubmitSpec{
400			id: "w", from: "chain-a", to: "chain-b", nonce: 5,
401			proofAt: 110, payload: "orig", expiresAt: 9_000_000_000_000,
402		}
403		mustSubmit(t, state, spec)
404		advanceCLI(t, state, 1_700_000_000_000)
405		before := queryFull(t, state, "w")
406		if before.Status != "waiting" || before.Attempts != 1 || before.NextRetry != 1_700_000_001_000 {
407			t.Fatalf("setup waiting record wrong: %+v", before)
408		}
409	
410		mutations := []struct {
411			name   string
412			mutate func(*cliSubmitSpec)
413		}{
414			{"proof height only", func(s *cliSubmitSpec) { s.proofAt = 111 }},
415			{"expiry only", func(s *cliSubmitSpec) { s.expiresAt = 9_000_000_000_001 }},
416			{"payload only", func(s *cliSubmitSpec) { s.payload = "changed" }},
417			{"nonce only", func(s *cliSubmitSpec) { s.nonce = 6 }},
418			{"destination only", func(s *cliSubmitSpec) { s.to = "chain-c" }},
419		}
420		for _, tc := range mutations {
421			t.Run(tc.name, func(t *testing.T) {
422				changed := spec
423				tc.mutate(&changed)
424				assertContentConflict(t, submitRaw(t, state, changed), "w")
425				if got := queryFull(t, state, "w"); got != before {
426					t.Fatalf("waiting record changed after rejected submit:\nbefore=%+v\nafter =%+v", before, got)
427				}
428			})
429		}
430	
431		early := advanceCLI(t, state, 1_700_000_000_500)
432		if len(early.Results) != 0 {
433			t.Fatalf("rejected submits must not reschedule or trigger processing: %+v", early.Results)
434		}
435		if got := queryFull(t, state, "w"); got != before {
436			t.Fatalf("waiting record changed on early advance: %+v", got)
437		}
438	
439		// Trusted 110 covers the original proof height 110; the rejected 111 would
440		// still wait. Success at the scheduled retry proves the original content
441		// was kept and never processed early.
442		if r := storeHeader(t, state, "chain-a", 110, "0x110", true); r.code != 0 {
443			t.Fatalf("extend coverage: %v", r)
444		}
445		rep := advanceCLI(t, state, 1_700_000_001_000)
446		got := resultFor(t, rep, "w")
447		if got.Status != "success" ||
448			got.Reason != "delivered; proof verified by trusted header at height 110" {
449			t.Fatalf("message must deliver by its original proof height 110: %+v", got)
450		}
451	}
