453	// A rejected submit changes neither the target message nor any other message
454	// in the same directory: sibling content stays intact and the first-submission
455	// order of all three ids is unchanged when they are later processed.
456	func TestCLISubmitConflictLeavesSiblingsAndOrderUntouched(t *testing.T) {
457		state := t.TempDir()
458		registerSource(t, state, "chain-a")
459		if r := storeHeader(t, state, "chain-a", 200, "0x200", true); r.code != 0 {
460			t.Fatalf("store header: %v", r)
461		}
462	
463		a := cliSubmitSpec{id: "a1", from: "chain-a", to: "chain-b", nonce: 1, proofAt: 10, payload: "pa", expiresAt: 9_000_000_000_000}
464		m := cliSubmitSpec{id: "mid", from: "chain-a", to: "chain-b", nonce: 5, proofAt: 100, payload: "original", expiresAt: 9_000_000_000_000}
465		b := cliSubmitSpec{id: "b1", from: "chain-a", to: "chain-b", nonce: 9, proofAt: 200, payload: "pb", expiresAt: 9_000_000_000_000}
466		mustSubmit(t, state, a)
467		mustSubmit(t, state, m)
468		mustSubmit(t, state, b)
469	
470		badProof := m
471		badProof.proofAt = 101
472		assertContentConflict(t, submitRaw(t, state, badProof), "mid")
473		badPayload := m
474		badPayload.payload = "changed"
475		assertContentConflict(t, submitRaw(t, state, badPayload), "mid")
476	
477		all := queryAll(t, state)
478		if got := recordIDs(all); len(got) != 3 || got[0] != "a1" || got[1] != "mid" || got[2] != "b1" {
479			t.Fatalf("order/content must survive rejected submits: %v", got)
480		}
481		got := map[string]cliFullRecord{}
482		for _, r := range all {
483			got[r.ID] = r
484		}
485		if got["mid"].ProofAt != 100 || got["mid"].Payload != "original" {
486			t.Fatalf("target content overwritten: %+v", got["mid"])
487		}
488		if got["a1"].ProofAt != 10 || got["a1"].Payload != "pa" ||
489			got["b1"].ProofAt != 200 || got["b1"].Payload != "pb" {
490			t.Fatalf("sibling content changed: a1=%+v b1=%+v", got["a1"], got["b1"])
491		}
492	
493		// All three process in original submission order using their original content.
494		rep := advanceCLI(t, state, 1_700_000_000_000)
495		if len(rep.Results) != 3 {
496			t.Fatalf("want 3 delivery results, got %+v", rep.Results)
497		}
498		for i, wantID := range []string{"a1", "mid", "b1"} {
499			if rep.Results[i].ID != wantID || rep.Results[i].Status != "success" {
500				t.Fatalf("position %d: want %s success, got %+v", i, wantID, rep.Results[i])
501			}
502		}
503	}
