514			t.Fatalf("store header: %v", r)
515		}
516		spec := cliSubmitSpec{
517			id: "s", from: "chain-a", to: "chain-b", nonce: 7,
518			proofAt: 90, payload: "hello", expiresAt: 9_000_000_000_000,
519		}
520		mustSubmit(t, state, spec)
521		rep := advanceCLI(t, state, 1_700_000_000_000)
522		if got := resultFor(t, rep, "s"); got.Status != "success" ||
523			got.Reason != "delivered; proof verified by trusted header at height 100" {
524			t.Fatalf("setup delivery wrong: %+v", got)
525		}
526		before := queryFull(t, state, "s")
527	
528		// Identical content: terminal, not an idempotent success echo.
529		assertTerminalReject(t, submitRaw(t, state, spec), "s", "success")
530	
531		// Different content in any field is still 14, never a 13 content conflict.
532		for _, tc := range []struct {
533			name   string
534			mutate func(*cliSubmitSpec)
535		}{
536			{"proof height", func(s *cliSubmitSpec) { s.proofAt = 91 }},
537			{"payload", func(s *cliSubmitSpec) { s.payload = "x" }},
538			{"expiry", func(s *cliSubmitSpec) { s.expiresAt = 9_000_000_000_001 }},
539			{"nonce", func(s *cliSubmitSpec) { s.nonce = 8 }},
540			{"source", func(s *cliSubmitSpec) { s.from = "chain-a2" }},
541			{"destination", func(s *cliSubmitSpec) { s.to = "chain-c" }},
542		} {
543			t.Run(tc.name, func(t *testing.T) {
544				changed := spec
545				tc.mutate(&changed)
546				assertTerminalReject(t, submitRaw(t, state, changed), "s", "success")
547			})
548		}
549	
550		if got := queryFull(t, state, "s"); got != before {
551			t.Fatalf("success record changed after rejected resubmits:\nbefore=%+v\nafter =%+v", before, got)
552		}
553		if all := queryAll(t, state); len(all) != 1 || all[0].ID != "s" {
554			t.Fatalf("rejected resubmit must not add an entry: %+v", all)
555		}
556	
557		// A higher trusted header and another advance must not resurrect or
558		// redeliver the terminal message.
559		if r := storeHeader(t, state, "chain-a", 120, "0x120", true); r.code != 0 {
560			t.Fatalf("extend coverage: %v", r)
561		}
562		again := advanceCLI(t, state, 1_700_000_100_000)
563		if len(again.Results) != 0 {
564			t.Fatalf("delivered message must not reappear on later advances: %+v", again.Results)
565		}
566		if got := queryFull(t, state, "s"); got != before {
567			t.Fatalf("success record changed after re-advance:\nbefore=%+v\nafter =%+v", before, got)
568		}
569	}
570	
571	// Every terminal status, not just success, permanently rejects the id with 14
572	// for identical and differing content alike, while the stored status and reason
573	// stay queryable and unchanged.
574	func TestCLISubmitTerminalIDsRejectedWith14AcrossStatuses(t *testing.T) {
575		t.Run("expired", func(t *testing.T) {
576			state := t.TempDir()
577			registerSource(t, state, "chain-a")
578			spec := cliSubmitSpec{
579				id: "e", from: "chain-a", to: "chain-b", nonce: 1,
580				proofAt: 100, payload: "p", expiresAt: 1000,
581			}
582			mustSubmit(t, state, spec)
583			rep := advanceCLI(t, state, 1000) // now == expiry counts as expired
584			if got := resultFor(t, rep, "e"); got.Status != "expired" {
585				t.Fatalf("setup: want expired, got %+v", got)
586			}
587			before := queryFull(t, state, "e")
588			assertTerminalReject(t, submitRaw(t, state, spec), "e", "expired")
589			changed := spec
590			changed.proofAt = 101
591			assertTerminalReject(t, submitRaw(t, state, changed), "e", "expired")
592			if got := queryFull(t, state, "e"); got != before {
593				t.Fatalf("expired record changed: %+v", got)
594			}
595		})
596	
597		t.Run("unknown-source", func(t *testing.T) {
598			state := t.TempDir()
599			spec := cliSubmitSpec{
600				id: "u", from: "chain-ghost", to: "chain-b", nonce: 1,
601				proofAt: 10, payload: "p", expiresAt: 9_000_000_000_000,
602			}
603			mustSubmit(t, state, spec)
604			rep := advanceCLI(t, state, 1000)
605			if got := resultFor(t, rep, "u"); got.Status != "unknown-source" {
606				t.Fatalf("setup: want unknown-source, got %+v", got)
607			}
608			before := queryFull(t, state, "u")
609			assertTerminalReject(t, submitRaw(t, state, spec), "u", "unknown-source")
610			changed := spec
611			changed.payload = "different"
612			assertTerminalReject(t, submitRaw(t, state, changed), "u", "unknown-source")
613			if got := queryFull(t, state, "u"); got != before {
614				t.Fatalf("unknown-source record changed: %+v", got)
615			}
616		})
617	
618		t.Run("replay", func(t *testing.T) {
619			state := t.TempDir()
620			registerSource(t, state, "chain-a")
621			if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
622				t.Fatalf("store header: %v", r)
623			}
624			winner := cliSubmitSpec{
625				id: "win", from: "chain-a", to: "chain-b", nonce: 3,
626				proofAt: 10, payload: "w", expiresAt: 9_000_000_000_000,
627			}
628			loser := cliSubmitSpec{
629				id: "lose", from: "chain-a", to: "chain-b", nonce: 3,
630				proofAt: 10, payload: "l", expiresAt: 9_000_000_000_000,
631			}
632			mustSubmit(t, state, winner)
633			mustSubmit(t, state, loser)
634			rep := advanceCLI(t, state, 1000)
635			if got := resultFor(t, rep, "lose"); got.Status != "replay" {
636				t.Fatalf("setup: want replay, got %+v", got)
637			}
638			before := queryFull(t, state, "lose")
639			assertTerminalReject(t, submitRaw(t, state, loser), "lose", "replay")
640			changed := loser
641			changed.payload = "changed"
642			assertTerminalReject(t, submitRaw(t, state, changed), "lose", "replay")
643			if got := queryFull(t, state, "lose"); got != before {
644				t.Fatalf("replay record changed: %+v", got)
645			}
646		})
647	}
